/**
 * DeltaPill — arrow glyph + signed numeric value pill.
 *
 * Never color-alone: three encodings — arrow glyph direction, signed numeric
 * value (+/-), and color. role="status" (polite live region).
 *
 * `goodDirection`: for error-rate and latency a downward delta is good news.
 * The arrow glyph always reflects the actual direction of change; the color
 * reflects whether that direction is desirable.
 *
 * Design doc §1.2.
 */

import type { ReactElement } from "react";
import { ArrowUp, ArrowDown, ArrowRight } from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export type GoodDirection = "up" | "down";

export interface DeltaPillProps {
  /** The numeric delta (positive = up, negative = down, 0 = flat). */
  value: number;
  /** Unit string shown in the pill (e.g. "%" or "ms"). */
  unit: string;
  /** When set, inverts the color for a "good" downward or upward direction. */
  goodDirection?: GoodDirection;
}

type Direction = "up" | "down" | "flat";

const FLAT_THRESHOLD = 0.005; // treat |delta| below this as flat

// Arrow icons — one lucide component per direction (aria-hidden, decorative).
const ARROW_ICON: Record<Direction, ReactElement> = {
  up: <ArrowUp aria-hidden="true" className="h-cog-3 w-cog-3" />,
  down: <ArrowDown aria-hidden="true" className="h-cog-3 w-cog-3" />,
  flat: <ArrowRight aria-hidden="true" className="h-cog-3 w-cog-3" />,
};

// Determine the color variant:
//   up   → success bg/text  (or danger when goodDirection === "down")
//   down → danger bg/text   (or success when goodDirection === "down")
//   flat → neutral
type ColorVariant = "success" | "danger" | "neutral";

function resolveVariant(
  direction: Direction,
  goodDirection?: GoodDirection,
): ColorVariant {
  if (direction === "flat") return "neutral";
  const isGood =
    goodDirection == null
      ? false
      : direction === goodDirection; // direction matches the "good" direction
  if (direction === "up") return isGood ? "success" : "danger";
  return isGood ? "success" : "danger";
}

// Tailwind classes per color variant (light + dark, per design doc §1.2)
const VARIANT_CLASSES: Record<ColorVariant, string> = {
  success: [
    "bg-cog-success-50 text-cog-success-500",
    "dark:bg-cog-success-950 dark:text-cog-success-300",
  ].join(" "),
  danger: [
    "bg-cog-danger-50 text-cog-danger-500",
    "dark:bg-cog-danger-950 dark:text-cog-danger-dark",
  ].join(" "),
  neutral: [
    "bg-cog-surface-muted text-cog-text-secondary",
    "dark:bg-cog-surface-muted dark:text-cog-text-secondary",
  ].join(" "),
};

export function DeltaPill({
  value,
  unit,
  goodDirection,
}: DeltaPillProps): ReactElement {
  const direction: Direction =
    Math.abs(value) < FLAT_THRESHOLD ? "flat" : value > 0 ? "up" : "down";

  const variant = resolveVariant(direction, goodDirection);
  const absValue = Math.abs(value);
  const formattedValue = absValue % 1 === 0 ? String(absValue) : absValue.toFixed(2);
  const displayText = direction === "flat" ? "±0" : `${direction === "up" ? "+" : "−"}${formattedValue}${unit}`;

  const ariaLabel =
    direction === "up"
      ? m.admin_health_delta_up({ value: formattedValue, unit })
      : direction === "down"
        ? m.admin_health_delta_down({ value: formattedValue, unit })
        : m.admin_health_delta_flat();

  return (
    <span
      role="status"
      aria-label={ariaLabel}
      className={[
        "inline-flex items-center gap-cog-1 rounded-pill px-cog-2 py-cog-0-5",
        "text-caption font-semibold",
        VARIANT_CLASSES[variant],
      ].join(" ")}
    >
      {ARROW_ICON[direction]}
      <span>{displayText}</span>
    </span>
  );
}


