/**
 * HealthStatTile — one of the four headline stat tiles.
 *
 * Design doc §2.1: role="group" aria-label, JetBrains Mono 700 tabular-nums,
 * status-driven border treatment, SparklineSVG + DeltaPill row.
 * Artboard: redesign-stat-light / redesign-stat-dark.
 */

import type { ReactElement } from "react";
import { SparklineSVG, type SparklineTone } from "./SparklineSVG";
import { DeltaPill, type GoodDirection } from "./DeltaPill";
import type { HealthStatus } from "../api/systemHealth";

export interface HealthStatTileProps {
  label: string;
  /** Formatted display value (e.g. "99.82" or "42.5"). */
  value: string;
  /** Unit string (e.g. "%" or "ms"). Empty for dimensionless counts. */
  unit: string;
  /** Raw numeric delta for DeltaPill. */
  delta: number;
  sparkline: number[];
  status: HealthStatus;
  sparklineTone: SparklineTone;
  goodDirection?: GoodDirection;
}

// Status → border class (design doc §2.1 border treatment).
const STATUS_BORDER: Record<HealthStatus, string> = {
  operational: "border-cog-divider dark:border-cog-divider",
  degraded:
    "border-cog-warning-300 dark:border-cog-amber-700",
  outage:
    "border-cog-danger-200 dark:border-cog-danger-500",
  // "offline" used by service status, but headline only uses three:
  // operational/degraded/outage — map offline → outage styling.
  offline: "border-cog-danger-200 dark:border-cog-danger-500",
};

export function HealthStatTile({
  label,
  value,
  unit,
  delta,
  sparkline,
  status,
  sparklineTone,
  goodDirection,
}: HealthStatTileProps): ReactElement {
  const ariaLabel = unit ? `${label}, ${value}${unit}` : `${label}, ${value}`;
  const borderClass = STATUS_BORDER[status] ?? STATUS_BORDER.operational;

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className={[
        "flex min-h-cog-25 flex-col gap-cog-3",
        "rounded-lg border p-cog-4",
        "shadow-cog-e1 dark:shadow-cog-e1-dark",
        "bg-cog-surface dark:bg-cog-surface",
        borderClass,
      ].join(" ")}
    >
      {/* Label row */}
      <span className="text-body-sm font-semibold text-cog-text-secondary">
        {label}
      </span>

      {/* Value row */}
      <div className="flex items-baseline gap-cog-2">
        <span
          lang="en"
          className="font-mono text-heading-xl font-bold leading-none tabular-nums text-cog-text-primary dark:text-cog-text-primary"
        >
          {value}
        </span>
        {unit && (
          <span className="text-body-sm text-cog-text-tertiary">{unit}</span>
        )}
      </div>

      {/* Sparkline + delta row */}
      <div className="flex items-end justify-between gap-cog-2">
        <SparklineSVG points={sparkline} tone={sparklineTone} width={80} height={28} />
        <DeltaPill value={delta} unit={unit} goodDirection={goodDirection} />
      </div>
    </div>
  );
}


