/**
 * OpenStatusPageLink — trailing "Open status page →" anchor.
 *
 * Opens in a new tab with rel="noreferrer" (no opener + no referrer).
 * Screen reader gets sr-only "opens in new tab" text so users know the
 * navigation leaves the app (WCAG 3.2.2).
 *
 * Design doc §3.
 */

import type { ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { ExternalLink } from "@omnicore-platform/ui/icons";

export interface OpenStatusPageLinkProps {
  url: string;
}

export function OpenStatusPageLink({ url }: OpenStatusPageLinkProps): ReactElement {
  return (
    <a
      href={url}
      target="_blank"
      rel="noreferrer"
      className={[
        "inline-flex items-center gap-cog-1",
        "text-body-sm font-semibold text-cog-blue-600 hover:text-cog-blue-700",
        "underline decoration-transparent hover:decoration-current",
        "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-cog-focus",
        "rounded-sm transition-colors",
      ].join(" ")}
    >
      {m.admin_health_open_status_page()}
      {/* External link icon — aria-hidden, visual affordance only */}
      <ExternalLink
        aria-hidden="true"
        className="h-cog-3 w-cog-3 flex-shrink-0"
      />
      {/* Screen reader only — announces tab opens in new tab */}
      <span className="sr-only">{m.admin_health_opens_new_tab()}</span>
    </a>
  );
}


