/**
 * ServiceStatusList — card with column headers + one row per service.
 *
 * Design doc §2.2: grid-cols-[1fr_auto_auto_auto_auto], text-end for
 * logical RTL alignment, SparklineSVG width=56 height=20.
 */

import type { ReactElement } from "react";
import { SparklineSVG, type SparklineTone } from "./SparklineSVG";
import { StatusPill } from "./StatusPill";
import type { ServiceEntry, ServiceStatus } from "../api/systemHealth";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export interface ServiceStatusListProps {
  services: ServiceEntry[];
}

/**
 * Status → localized status label, as an explicit map of named function
 * references (never `m[...]` computed indexing — a computed index into the
 * `import * as m` namespace defeats Rollup's tree-shaking and inlines the
 * entire 11-locale message catalog into this MFE's bundle, even when the key
 * is type-safe). See studioTasks.ts:1-11 in studio-mfe for the same pattern.
 */
const STATUS_LABEL: Record<ServiceStatus, () => string> = {
  operational: m.admin_health_status_operational,
  degraded: m.admin_health_status_degraded,
  offline: m.admin_health_status_offline,
  unknown: m.admin_health_status_unknown,
};

// Status → sparkline tone (design doc §2.2)
function statusToTone(status: ServiceStatus): SparklineTone {
  switch (status) {
    case "degraded":
      return "warning";
    case "offline":
      return "danger";
    default:
      return "neutral";
  }
}

function formatPct(v: number): string {
  return v % 1 === 0 ? String(v) : v.toFixed(1);
}

function formatMs(v: number): string {
  return v % 1 === 0 ? String(v) : v.toFixed(1);
}

export function ServiceStatusList({
  services,
}: ServiceStatusListProps): ReactElement {
  return (
    <section
      aria-labelledby="service-list-heading"
      className="rounded-lg border border-cog-divider bg-cog-surface shadow-cog-e1 dark:shadow-cog-e1-dark p-cog-5"
    >
      <h2
        id="service-list-heading"
        className="text-heading-sm text-cog-text-primary mb-cog-4"
      >
        {m.admin_health_service_list_title()}
      </h2>

      {/* Column header row — visual aid only, aria-hidden */}
      <div
        role="row"
        aria-hidden="true"
        className="grid grid-cols-[1fr_auto_auto_auto_auto] gap-x-cog-4 px-cog-2 pb-cog-2 border-b border-cog-divider text-micro font-bold uppercase tracking-widest text-cog-text-tertiary"
      >
        <span>{m.admin_health_col_service()}</span>
        <span>{m.admin_health_col_trend()}</span>
        <span>{m.admin_health_col_uptime()}</span>
        <span>{m.admin_health_col_latency()}</span>
        <span>{m.admin_health_col_status()}</span>
      </div>

      {services.length === 0 ? (
        <p className="text-body-sm text-cog-text-tertiary py-cog-5 text-center">
          {m.admin_health_no_services()}
        </p>
      ) : (
        <ul className="divide-y divide-cog-divider">
          {services.map((svc) => {
            const statusLabel = STATUS_LABEL[svc.status]();
            const rowAriaLabel = `${svc.name}, ${statusLabel}, ${formatPct(svc.uptime_pct_7d)}% uptime`;
            return (
              <li
                key={svc.name}
                aria-label={rowAriaLabel}
                className="grid grid-cols-[1fr_auto_auto_auto_auto] items-center gap-x-cog-4 py-cog-3 px-cog-2"
              >
                {/* Service name */}
                <span className="truncate text-body-sm font-semibold text-cog-text-primary">
                  {svc.name}
                </span>

                {/* 7-day sparkline */}
                <SparklineSVG
                  points={svc.sparkline_7d}
                  tone={statusToTone(svc.status)}
                  width={56}
                  height={20}
                />

                {/* Uptime % */}
                <span className="w-cog-8-5 text-end text-body-sm tabular-nums text-cog-text-secondary">
                  <span lang="en">{formatPct(svc.uptime_pct_7d)}</span>%
                </span>

                {/* p95 latency */}
                <span className="w-cog-9 text-end text-body-sm tabular-nums text-cog-text-secondary">
                  <span lang="en">{formatMs(svc.p95_latency_ms)}</span>
                  <span className="text-micro text-cog-text-tertiary ms-cog-0-5">
                    {m.admin_health_unit_ms()}
                  </span>
                </span>

                {/* Status pill */}
                <div className="flex w-cog-11 justify-end">
                  <StatusPill status={svc.status} />
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}


