/**
 * StatusPill — service status pill with dot + label + color encoding.
 *
 * Three encodings for WCAG 1.4.1 never-color-alone:
 *   1. dot shape (rounded-full circle)
 *   2. status WORD label (text)
 *   3. color (bg + text + border)
 *
 * Uses @omnicore-platform/ui Badge as the visual base but wraps it with
 * role="status" and aria-label because Badge does not carry those semantics.
 *
 * Design doc §1.3.
 */

import type { ReactElement } from "react";
import { Badge } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { ServiceStatus } from "../api/systemHealth";

export interface StatusPillProps {
  status: ServiceStatus;
}

type BadgeVariant = "success" | "danger" | "neutral";

// Tailwind warning variant is not in Badge — we handle "degraded" with a
// custom className override since Badge only has success/danger/neutral/info/live.
const STATUS_LABEL: Record<ServiceStatus, () => string> = {
  operational: m.admin_health_status_operational,
  degraded: m.admin_health_status_degraded,
  offline: m.admin_health_status_offline,
  unknown: m.admin_health_status_unknown,
};

// Map service status to the closest Badge variant + optional className override.
const STATUS_TO_VARIANT: Record<ServiceStatus, BadgeVariant> = {
  operational: "success",
  degraded: "neutral", // overridden below with warning classes
  offline: "danger",
  unknown: "neutral",
};

// "degraded" needs warning colours not available on neutral Badge variant.
// We compose with className override (twMerge last-wins in cn()).
const DEGRADED_OVERRIDE = [
  "bg-cog-warning-50 text-cog-warning-700 border-cog-warning-300",
  "dark:bg-cog-warning-950 dark:text-cog-amber-400 dark:border-cog-amber-700",
].join(" ");

export function StatusPill({ status }: StatusPillProps): ReactElement {
  const label = STATUS_LABEL[status]();
  const variant = STATUS_TO_VARIANT[status];
  const extra = status === "degraded" ? DEGRADED_OVERRIDE : undefined;

  return (
    <Badge
      variant={variant}
      dot
      role="status"
      aria-label={label}
      className={extra}
    >
      {label}
    </Badge>
  );
}


--- frontends/admin-mfe/src/systemHealth/UptimeHistogram.tsx (162 lines) ---
/**
 * UptimeHistogram — 90 per-day bars per service.
 *
 * Core honesty contract (spec §4 / §7):
 *   - ALWAYS renders 90 bars per service.
 *   - Pre-history bars (status="unknown") MUST use cog-surface-muted —
 *     never any tint of green. Grey = "no data".
 *   - "N of 90 days of data" caption when available_days < history_days.
 *
 * The bar strip carries dir="ltr" explicitly — time does not mirror for
 * RTL locales (oldest→newest is always left→right on a heatmap).
 * An aria-description in Arabic explains this to screen reader users.
 *
 * Design doc §1.4 + §5.5.
 */

import type { ReactElement } from "react";
import type { HistoryEntry, DayStatus } from "../api/systemHealth";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

export interface UptimeHistogramProps {
  services: HistoryEntry[];
  available_days: number;
  history_days: number;
}

// Bar fill classes per day status (design doc §1.4 bar colors + tokens).
const BAR_COLOR: Record<DayStatus, string> = {
  operational: "bg-cog-success-50 dark:bg-cog-success-dark-bg",
  degraded: "bg-cog-warning-50 dark:bg-cog-warning-950",
  outage: "bg-cog-danger-50 dark:bg-cog-danger-dark-bg",
  // unknown MUST be cog-surface-muted — never green.
  unknown: "bg-cog-surface-muted",
};

interface LegendItemProps {
  status: DayStatus;
  label: string;
}

function LegendItem({ status, label }: LegendItemProps): ReactElement {
  return (
    <div role="listitem" className="flex items-center gap-cog-1">
      <span
        aria-hidden="true"
        className={`h-cog-1-5 w-cog-3 rounded-sm flex-shrink-0 ${BAR_COLOR[status]}`}
      />
      <span className="text-caption text-cog-text-secondary">{label}</span>
    </div>
  );
}

export function UptimeHistogram({
  services,
  available_days,
  history_days,
}: UptimeHistogramProps): ReactElement {
  const showCaption = available_days < history_days;
  const ltrNote = m.admin_health_heatmap_time_ltr_note();

  return (
    <div className="flex flex-col gap-cog-3">
      {/* role="list" wraps ONLY the per-service rows below — the Legend is a
       * sibling outside it, not a child, since a valid ARIA list may only
       * directly contain role="listitem" children (aria-required-children).
       * className="contents" keeps this wrapper invisible to layout so the
       * flex-col/gap spacing above still applies as if it weren't there. */}
      <div role="list" className="contents">
      {services.map((svc) => (
        <div
          role="listitem"
          key={svc.name}
          className="flex flex-col gap-cog-2"
        >
          <div className="flex items-center justify-between">
            <span className="text-body-sm font-semibold text-cog-text-secondary">
              {svc.name}
            </span>
            {showCaption && (
              <span className="text-caption text-cog-text-tertiary">
                {m.admin_health_history_window({
                  available: available_days,
                  total: history_days,
                })}
              </span>
            )}
          </div>

          {/* Bar strip — forced LTR for time-axis correctness in RTL documents.
           * aria-description is not supported on role="list" (jsx-a11y
           * role-supports-aria-props) and has weak AT support even where it
           * is valid, so the LTR note is rendered as a real (visually
           * hidden) element and wired via aria-describedby instead. It is
           * rendered as a sibling of the list, not a child, so the list's
           * only children remain role="listitem" bars. */}
          {ltrNote && (
            <span id={`uptime-histogram-ltr-note-${svc.name}`} className="sr-only">
              {ltrNote}
            </span>
          )}
          <div
            role="list"
            aria-label={`90-day uptime history for ${svc.name}`}
            aria-describedby={ltrNote ? `uptime-histogram-ltr-note-${svc.name}` : undefined}
            dir="ltr"
            className="flex items-end"
            style={{ gap: "1.5px" }}
          >
            {svc.days.map((day) => {
              const ariaLabel =
                day.status !== "unknown" && day.uptime_pct !== null
                  ? m.admin_health_bar_aria({
                      date: day.date,
                      pct: day.uptime_pct,
                    })
                  : m.admin_health_bar_aria_unknown({ date: day.date });

              return (
                <div
                  role="listitem"
                  key={day.date}
                  title={
                    day.status !== "unknown" && day.uptime_pct !== null
                      ? `${day.date}: ${day.uptime_pct}%`
                      : day.date
                  }
                  aria-label={ariaLabel}
                  className={[
                    "h-cog-4 w-full min-w-cog-0 flex-1 rounded-sm",
                    BAR_COLOR[day.status],
