/**
 * SparklineSVG — compact inline SVG polyline (no chart primitive in ui/).
 * aria-hidden: the numeric value + DeltaPill are the accessible affordances.
 *
 * Design doc §1.1: viewBox "0 0 80 28", preserveAspectRatio="none",
 * stroke-width 1.75, end-dot r=2, flat line at midpoint when max===min.
 * Time axis is LTR in SVG coord space regardless of document direction
 * (time does not mirror for RTL locales).
 */

import type { ReactElement } from "react";

export type SparklineTone = "neutral" | "success" | "warning" | "danger";

export interface SparklineSVGProps {
  /** Raw data values (not pre-normalised). */
  points: number[];
  /** Color tone — mapped to cog status ramp. */
  tone: SparklineTone;
  /** Rendered width (px). ViewBox stays 80×28. */
  width?: number;
  /** Rendered height (px). ViewBox stays 80×28. */
  height?: number;
}

// Tone → Tailwind stroke class (light + dark).
const TONE_STROKE: Record<SparklineTone, string> = {
  // cog-blue-600 light / cog-blue-300 dark
  neutral: "stroke-cog-blue-600 dark:stroke-cog-blue-300",
  // cog-success-500 light / cog-success-dark dark
  success: "stroke-cog-success-500 dark:stroke-cog-success-300",
  // cog-warning-700 light / cog-warning-dark-text dark
  warning: "stroke-cog-amber-700 dark:stroke-cog-amber-400",
  // cog-danger-500 light / cog-danger-dark dark
  danger: "stroke-cog-danger-500 dark:stroke-cog-danger-dark",
};

/** Normalise raw values into the 80×28 SVG coordinate space. */
function normalise(rawPoints: number[]): { x: number; y: number }[] {
  const count = rawPoints.length;
  if (count === 0) return [];
  if (count === 1) return [{ x: 40, y: 14 }];

  const min = Math.min(...rawPoints);
  const max = Math.max(...rawPoints);
  const range = max - min;

  return rawPoints.map((v, i) => ({
    x: (i / (count - 1)) * 80,
    // Leave 2px padding top/bottom: map into y∈[2, 26].
    y: range === 0 ? 14 : 26 - ((v - min) / range) * 24,
  }));
}

export function SparklineSVG({
  points,
  tone,
  width = 80,
  height = 28,
}: SparklineSVGProps): ReactElement {
  const coords = normalise(points);
  const strokeClass = TONE_STROKE[tone];

  const pointsAttr =
    coords.length >= 2
      ? coords.map(({ x, y }) => `${x},${y}`).join(" ")
      : null;

  const last = coords[coords.length - 1];

  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox="0 0 80 28"
      preserveAspectRatio="none"
      width={width}
      height={height}
      className="flex-shrink-0 overflow-visible"
    >
      {pointsAttr && (
        <polyline
          points={pointsAttr}
          fill="none"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
          className={strokeClass}
        />
      )}
      {last && (
        <circle
          cx={last.x}
          cy={last.y}
          r="2"
          className={`${strokeClass.replace("stroke-", "fill-")} stroke-none`}
        />
      )}
    </svg>
  );
}


