            role="list"
            aria-label={`90-day uptime history for ${svc.name}`}
            aria-describedby={ltrNote ? `uptime-histogram-ltr-note-${svc.name}` : undefined}
            dir="ltr"
            className="flex items-end"
            style={{ gap: "1.5px" }}
          >
            {svc.days.map((day) => {
              const ariaLabel =
                day.status !== "unknown" && day.uptime_pct !== null
                  ? m.admin_health_bar_aria({
                      date: day.date,
                      pct: day.uptime_pct,
                    })
                  : m.admin_health_bar_aria_unknown({ date: day.date });

              return (
                <div
                  role="listitem"
                  key={day.date}
                  title={
                    day.status !== "unknown" && day.uptime_pct !== null
                      ? `${day.date}: ${day.uptime_pct}%`
                      : day.date
                  }
                  aria-label={ariaLabel}
                  className={[
                    "h-cog-4 w-full min-w-cog-0 flex-1 rounded-sm",
                    BAR_COLOR[day.status],
                  ].join(" ")}
                />
              );
            })}
          </div>
        </div>
      ))}
      </div>

      {/* Legend */}
      <div role="list" aria-label="Legend" className="flex items-center gap-cog-4 mt-cog-3 flex-wrap">
        <LegendItem
          status="operational"
          label={m.admin_health_history_legend_operational()}
        />
        <LegendItem
          status="degraded"
          label={m.admin_health_history_legend_degraded()}
        />
        <LegendItem
          status="outage"
          label={m.admin_health_history_legend_outage()}
        />
        <LegendItem
          status="unknown"
          label={m.admin_health_history_legend_unknown()}
        />
      </div>
    </div>
  );
