/**
 * useSystemHealth — loads system health from admin-bff into a discriminated
 * loading/ready/error/unavailable state. `reload()` re-fetches.
 *
 * Discriminated union:
 *   { state: "loading" }
 *   { state: "ready"; health: SystemHealth }
 *   { state: "error"; message: string }
 *   { state: "unavailable" }  — 503 prometheus_unavailable arm
 *
 * Mirrors useApiKeys.ts: mounted-ref guard prevents setS() after unmount.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { fetchSystemHealth, type SystemHealth } from "../api/systemHealth";

type State =
  | { state: "loading" }
  | { state: "ready"; health: SystemHealth }
  | { state: "error"; message: string }
  | { state: "unavailable" };

export function useSystemHealth(): State & { reload: () => void } {
  const [s, setS] = useState<State>({ state: "loading" });
  // Prevents state updates after unmount (mirrors useApiKeys.ts pattern).
  const mountedRef = useRef(true);

  const reload = useCallback(() => {
    setS({ state: "loading" });
    fetchSystemHealth().then((result) => {
      if (!mountedRef.current) return;
      if (result.ok) {
        setS({ state: "ready", health: result.health });
      } else if (result.unavailable) {
        setS({ state: "unavailable" });
      } else {
        setS({ state: "error", message: result.message });
      }
    });
  }, []);

  useEffect(() => {
    mountedRef.current = true;
    reload();
    return () => {
      mountedRef.current = false;
    };
  }, [reload]);

  return { ...s, reload };
}



